import {validateMessage} from './validation.js';

describe('list_sessions validation', () => {
  // specs/hal-engine-conversation-list/spec.md#40
  it('validates paging and strips fields outside the list frame', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
    const before = {sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z'};
    expect(validateMessage({type: 'list_sessions', limit: 0, before, userId: 'other'})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 0, before},
    });
    expect(validateMessage({type: 'list_sessions', before: {sessionId: 's', updatedAt: 0}}).valid).toBe(true);
    for (const limit of [-1, 1.5, '1']) {
      expect(validateMessage({type: 'list_sessions', limit}).valid).toBe(false);
    }
    for (const cursor of [null, {}, {sessionId: '', updatedAt: 0}, {sessionId: 'x'.repeat(129), updatedAt: 0}, {sessionId: 's', updatedAt: 'bad'}, {sessionId: 's', updatedAt: Infinity}]) {
      expect(validateMessage({type: 'list_sessions', before: cursor}).valid).toBe(false);
    }
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/transport/ws/listSessionsValidation.test.ts"

